// Run with Playwright available on NODE_PATH and a fixture generated by:
// mvn test -Dslider.fixture=/tmp/bjyo-slider-fixture.json
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const assert = require('node:assert/strict');
const { chromium } = require('playwright');
const root = path.resolve(__dirname, '../..');
const resources = path.join(root, 'bjyo-admin/src/main/resources');
const fixture = JSON.parse(fs.readFileSync(process.env.SLIDER_FIXTURE || '/tmp/bjyo-slider-fixture.json', 'utf8'));
const output = process.env.SLIDER_OUTPUT || path.join(root, 'docs/verification/login-slider-20261011');
fs.mkdirSync(output, { recursive: true });
let verifyOffsets = [], captchaCount = 0, failLoad = false, loginCount = 0;
let html = fs.readFileSync(path.join(resources, 'templates/login.html'), 'utf8');
html = html.replace(/(href|src)="[^"]*"\s+th:\1="@\{([^}]*)\}"/g, (_, attr, url) => `${attr}="/app${url}"`)
  .replace(/<script th:inline="javascript">[\s\S]*?<\/script>/, '<script>var ctx="/app/"; var captchaType="math"; var captchaEnabled=true;</script>');
const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = value => { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(value)); };
  if (url.pathname === '/app/login' && req.method === 'GET') { res.setHeader('Content-Type', 'text/html'); res.end(html); return; }
  if (url.pathname === '/app/login' && req.method === 'POST') {
    loginCount++; req.resume(); send({ code: 500, msg: '浏览器测试：密码错误' }); return;
  }
  if (url.pathname === '/app/captcha/slider') {
    captchaCount++;
    if (failLoad) { res.statusCode = 503; res.end(); return; }
    send({ code: 0, captchaEnabled: true, data: fixture }); return;
  }
  if (url.pathname === '/app/captcha/slider/verify') {
    let body = ''; req.on('data', chunk => body += chunk);
    req.on('end', () => { const data = JSON.parse(body); verifyOffsets.push(data.offset);
      send(data.offset === 82 ? { code: 0, data: 'B'.repeat(32) } : { code: 500, msg: '验证失败' }); }); return;
  }
  const file = path.resolve(resources, 'static', url.pathname.replace(/^\/app\//, ''));
  if (file.startsWith(path.join(resources, 'static') + path.sep) && fs.existsSync(file) && fs.statSync(file).isFile()) {
    const ext = path.extname(file);
    res.setHeader('Content-Type', ({ '.js': 'application/javascript', '.css': 'text/css', '.png': 'image/png', '.jpg': 'image/jpeg' })[ext] || 'application/octet-stream');
    fs.createReadStream(file).pipe(res); return;
  }
  res.statusCode = 404; res.end();
});

(async () => {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = []; page.on('pageerror', error => errors.push(error.message));
  const checks = [];
  try {
    await page.goto(`http://127.0.0.1:${server.address().port}/app/login`);
    await page.locator('#auth-username').fill('fixture_admin');
    await page.locator('#auth-password').fill('fixture_password');
    await page.locator('#btnSubmit').click();
    await page.locator('#slider-captcha-dialog').waitFor({ state: 'visible' });
    await page.waitForFunction(() => !document.getElementById('slider-handle').disabled);
    assert.equal(loginCount, 0); checks.push('未验证登录打开弹窗且不发送密码');
    await page.screenshot({ path: path.join(output, 'desktop.png'), fullPage: true });

    const handle = page.locator('#slider-handle');
    let box = await handle.boundingBox();
    await page.mouse.move(box.x + 20, box.y + 20); await page.mouse.down();
    await page.mouse.move(box.x + 45, box.y + 20, { steps: 5 }); await page.mouse.up();
    await page.waitForFunction(() => document.getElementById('slider-status').textContent.includes('验证失败'));
    assert(verifyOffsets[0] !== 82); checks.push('错误拖动展示失败并禁用过期挑战');
    await page.locator('#slider-refresh').click();
    await page.waitForFunction(() => !document.getElementById('slider-handle').disabled);
    const track = await page.locator('#slider-track').boundingBox(); box = await handle.boundingBox();
    await page.mouse.move(box.x + 20, box.y + 20); await page.mouse.down();
    await page.mouse.move(box.x + 20 + 82 / 268 * (track.width - box.width), box.y + 20, { steps: 10 });
    await page.mouse.up();
    await page.locator('#slider-captcha-dialog').waitFor({ state: 'hidden' });
    assert.equal(verifyOffsets[1], 82);
    assert.equal(await page.locator('#slider-trigger-label').textContent(), '安全验证已通过');
    checks.push('鼠标拖动按实际宽度提交82并显示通过');
    await page.locator('#btnSubmit').click();
    await page.waitForFunction(() => !document.getElementById('slider-captcha-trigger').disabled);
    assert.equal(loginCount, 1); checks.push('密码错误后清除验证凭证');
    await page.evaluate(() => window.layer.closeAll());

    await page.setViewportSize({ width: 320, height: 740 });
    await page.locator('#slider-captcha-trigger').click();
    await page.waitForFunction(() => !document.getElementById('slider-handle').disabled);
    const dialog = await page.locator('#slider-captcha-dialog').boundingBox();
    assert(dialog.x >= 0 && dialog.x + dialog.width <= 320);
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= 320));
    await page.screenshot({ path: path.join(output, 'mobile.png'), fullPage: true });
    checks.push('320px弹窗和页面无横向溢出');
    await handle.focus();
    for (let i = 0; i < 8; i++) await page.keyboard.press('Shift+ArrowRight');
    await page.keyboard.press('ArrowRight'); await page.keyboard.press('ArrowRight');
    assert.equal(await handle.getAttribute('aria-valuenow'), '82');
    await page.keyboard.press('Enter');
    await page.locator('#slider-captcha-dialog').waitFor({ state: 'hidden' });
    assert.equal(verifyOffsets[2], 82); checks.push('键盘方向键和回车完成验证');

    const expired = await page.evaluate(() => {
      const originalNow = Date.now; Date.now = () => originalNow() + 120001;
      try { return sliderCaptcha.getProof(); } finally { Date.now = originalNow; }
    });
    assert.equal(expired, undefined);
    assert.equal(await page.locator('#slider-trigger-label').textContent(), '点击进行安全验证');
    checks.push('两分钟后登录入口主动清除过期凭证');

    await page.evaluate(() => sliderCaptcha.reset());
    failLoad = true;
    await page.locator('#slider-captcha-trigger').click();
    await page.waitForFunction(() => document.getElementById('slider-status').textContent.includes('加载失败'));
    assert.equal(await handle.isDisabled(), true);
    failLoad = false; await page.locator('#slider-refresh').click();
    await page.waitForFunction(() => !document.getElementById('slider-handle').disabled);
    checks.push('加载失败后刷新可恢复');
    await page.keyboard.press('Escape');
    await page.locator('#slider-captcha-dialog').waitFor({ state: 'hidden' });
    await page.locator('#slider-captcha-trigger').click();
    await page.waitForFunction(() => !document.getElementById('slider-handle').disabled);
    checks.push('Escape关闭后重新打开加载新挑战');
    assert.deepEqual(errors, []);
    fs.writeFileSync(path.join(output, 'browser-results.json'), JSON.stringify({ checks, captchaCount, verifyOffsets, pageErrors: errors }, null, 2));
    console.log(JSON.stringify({ passed: checks.length, checks, pageErrors: errors }, null, 2));
  } finally { await browser.close(); await new Promise(resolve => server.close(resolve)); }
})().catch(error => { console.error(error); process.exitCode = 1; server.close(); });
